sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    /**
     * Initiates certificate auto-renewal after validating CSR options.
     * Validates the CSR payload based on selected option, closes the modal,
     * and executes the certificate renewal process.
     * 
     * @requires api.context.props.sysId - Certificate sys_id
     * @requires api.data.record.form.fields.valid_to - Certificate validity date
     * @requires api.state.renew_payload - CSR configuration from user selection
     * @requires api.state.validate_csr_alert - CSR validation results
     */

    const certificateSysId = api.context.props.sysId;
    const {
        csr_option_selected,
        csr_value,
        csr_validity_period,
        csr_decoded
    } = api.state.renew_payload;

    // For option1 (custom CSR), require valid CSR and validity period before proceeding
    const isOption1WithInvalidCsr = csr_option_selected === 'option1' &&
        (api.state.validate_csr_alert[0].status === 'critical' || api.state.validate_csr_alert[0].status == null || !csr_validity_period);

    if (isOption1WithInvalidCsr) {
        return;
    }

    // Close modal and execute renewal for valid option1 or any other option
    helpers.modal.close('renew_certificate_modal');

    api.data.executeCertificateAutoRenew.execute({
        certificateSysId: certificateSysId,
        csr: csr_value,
        validTo: csr_validity_period,
        csrDecoded: csr_decoded
    });
}
